using Microsoft.EntityFrameworkCore;
using RetailShop.Application.Common;
using RetailShop.Application.Finance;
using RetailShop.Domain.Finance;
using RetailShop.Infrastructure.Persistence;

namespace RetailShop.Infrastructure.Finance;

internal sealed class FinanceOperationsService(RetailShopDbContext db,IJournalPostingService posting,IFinanceAdministrationService administration):IFinanceOperationsService
{
 public async Task<FinanceSetupItem> SetupAsync(CancellationToken ct=default){var a=await db.FinanceActivations.AsNoTracking().SingleAsync(ct);const int required=18;var configured=await db.AccountMappings.CountAsync(x=>x.Type==AccountMappingType.System&&x.IsActive,ct);return new(a.AutomaticPostingEnabled,a.CutoverDate,a.MandatoryMappingsApproved,a.OpeningBalancesApproved,a.ReconciliationReady,Math.Max(0,required-configured),a.AutomaticPostingEnabled?"Active":"Finance Setup Mode");}
 public async Task<IReadOnlyCollection<FinanceAccountItem>> AccountsAsync(string? search,CancellationToken ct=default){var q=db.Accounts.AsNoTracking();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Code.Contains(search)||x.Name.Contains(search));return await q.OrderBy(x=>x.Code).Select(x=>Item(x)).ToArrayAsync(ct);}
 public async Task<OperationResult<FinanceAccountItem>> SaveAccountAsync(Guid? id,SaveFinanceAccountRequest r,CancellationToken ct=default){try{if(!id.HasValue){var x=new Account(r.Code,r.Name,r.Type,r.NormalBalance,r.Kind,r.ParentId);var z=await administration.CreateAccountAsync(x,ct);return z.Succeeded?OperationResult<FinanceAccountItem>.Success(Item(x)):OperationResult<FinanceAccountItem>.Failure(z.Errors);}var a=await db.Accounts.Include(x=>x.Parent).SingleOrDefaultAsync(x=>x.Id==id,ct);if(a is null)return OperationResult<FinanceAccountItem>.Failure("Account not found.");a.Rename(r.Name);if(a.HasPostings&&(a.Code!=r.Code.Trim().ToUpperInvariant()||a.Type!=r.Type||a.NormalBalance!=r.NormalBalance||a.Kind!=r.Kind||a.ParentId!=r.ParentId))return OperationResult<FinanceAccountItem>.Failure("Posted account identity cannot be changed.");if(!a.HasPostings)a.ChangeIdentity(r.Code,r.Type,r.NormalBalance,r.Kind,r.ParentId);if(r.ParentId is Guid p){var parent=await db.Accounts.Include(x=>x.Parent).SingleOrDefaultAsync(x=>x.Id==p,ct);a.AssignParent(parent);}a.SetActive(r.IsActive);await db.SaveChangesAsync(ct);return OperationResult<FinanceAccountItem>.Success(Item(a));}catch(Exception e)when(e is ArgumentException or InvalidOperationException or DbUpdateException){return OperationResult<FinanceAccountItem>.Failure(e.Message);}}
 public async Task<IReadOnlyCollection<FinancialAccountItem>> FinancialAccountsAsync(CancellationToken ct=default)=>await db.FinancialAccounts.AsNoTracking().Include(x=>x.Account).OrderBy(x=>x.Code).Select(x=>new FinancialAccountItem(x.Id,x.Code,x.Name,x.Type,x.AccountId,x.Account.Code,x.MaskedReference,x.IsActive,db.JournalLines.Where(l=>l.AccountId==x.AccountId).Sum(l=>(decimal?)(l.Debit-l.Credit))??0)).ToArrayAsync(ct);
 public async Task<OperationResult<FinancialAccountItem>> CreateFinancialAccountAsync(SaveFinancialAccountRequest r,CancellationToken ct=default){var x=new FinancialAccount(r.Code,r.Name,r.Type,r.AccountId,r.MaskedReference);var z=await administration.CreateFinancialAccountAsync(x,ct);if(!z.Succeeded)return OperationResult<FinancialAccountItem>.Failure(z.Errors);var a=await db.Accounts.SingleAsync(a=>a.Id==x.AccountId,ct);return OperationResult<FinancialAccountItem>.Success(new(x.Id,x.Code,x.Name,x.Type,x.AccountId,a.Code,x.MaskedReference,x.IsActive,0));}
 public async Task<IReadOnlyCollection<MappingItem>> MappingsAsync(CancellationToken ct=default)=>await db.AccountMappings.AsNoTracking().Include(x=>x.Account).OrderBy(x=>x.Type).ThenBy(x=>x.Key).Select(x=>new MappingItem(x.Id,x.Type,x.Key,x.AccountId,x.Account.Code,x.PaymentMethodId,x.ExpenseCategoryId,x.IsActive)).ToArrayAsync(ct);
 public async Task<OperationResult<MappingItem>> CreateMappingAsync(SaveMappingRequest r,CancellationToken ct=default){var x=new AccountMapping(r.Type,r.Key,r.AccountId,r.PaymentMethodId,r.ExpenseCategoryId);var z=await administration.SaveMappingAsync(x,ct);if(!z.Succeeded)return OperationResult<MappingItem>.Failure(z.Errors);var a=await db.Accounts.SingleAsync(a=>a.Id==x.AccountId,ct);return OperationResult<MappingItem>.Success(new(x.Id,x.Type,x.Key,x.AccountId,a.Code,x.PaymentMethodId,x.ExpenseCategoryId,x.IsActive));}
 public async Task<PagedResult<JournalQueryItem>> JournalsAsync(DateOnly? from,DateOnly? to,string? search,string? source,string? kind,Guid? accountId,int page,int size,CancellationToken ct=default){page=Math.Max(1,page);size=Math.Clamp(size,1,100);var q=db.JournalEntries.AsNoTracking().Include(x=>x.Lines).AsQueryable();if(from.HasValue)q=q.Where(x=>x.BusinessDate>=from);if(to.HasValue)q=q.Where(x=>x.BusinessDate<=to);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Number.Contains(search)||x.Description!.Contains(search));if(!string.IsNullOrWhiteSpace(source))q=q.Where(x=>x.SourceType==source);if(!string.IsNullOrWhiteSpace(kind))q=q.Where(x=>x.PostingKind==kind);if(accountId.HasValue)q=q.Where(x=>x.Lines.Any(l=>l.AccountId==accountId));var count=await q.CountAsync(ct);var items=await q.OrderByDescending(x=>x.BusinessDate).ThenByDescending(x=>x.PostedOn).Skip((page-1)*size).Take(size).Select(x=>new JournalQueryItem(x.Id,x.Number,x.BusinessDate,x.SourceType,x.SourceId,x.PostingKind,x.Description,x.PostedBy,x.ReversesJournalId,x.Lines.Sum(l=>l.Debit),x.Lines.Sum(l=>l.Credit))).ToArrayAsync(ct);return new(items,page,size,count);}
 public async Task<OperationResult<Guid>> SaveManualDraftAsync(ManualJournalRequest r,Guid by,CancellationToken ct=default){var d=new ManualJournalDraft(r.BusinessDate,r.Description,r.Reference,by);d.ReplaceLines(r.Lines.Select(x=>new ManualJournalDraftLine(x.AccountId,x.Debit,x.Credit,x.Description)));db.Add(d);await db.SaveChangesAsync(ct);return OperationResult<Guid>.Success(d.Id);}
 public async Task<OperationResult<JournalItem>> PostManualAsync(Guid id,Guid by,CancellationToken ct=default){var active=await Active(ct);if(!active)return OperationResult<JournalItem>.Failure("Finance must be explicitly activated before monetary posting.");var d=await db.ManualJournalDrafts.Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==id,ct);if(d is null||d.Status!=FinanceDocumentStatus.Draft)return OperationResult<JournalItem>.Failure("Manual journal draft was not found or is already posted.");var protectedIds=await db.AccountMappings.Where(x=>x.Type==AccountMappingType.System&&new[]{SystemAccountKeys.CustomerReceivables,SystemAccountKeys.SupplierPayables,SystemAccountKeys.InventoryAsset}.Contains(x.Key)).Select(x=>x.AccountId).ToArrayAsync(ct);if(d.Lines.Any(x=>protectedIds.Contains(x.AccountId)))return OperationResult<JournalItem>.Failure("Manual journals cannot post to protected AR, AP or Inventory control accounts.");var result=await posting.PostAsync(new(d.BusinessDate,"ManualJournal",d.Id,"Manual",d.Description,d.Lines.Select(x=>new JournalLineRequest(x.AccountId,x.Debit,x.Credit,x.Description)).ToArray()),by,ct);if(result.Succeeded){d.MarkPosted(result.Value!.Id);await db.SaveChangesAsync(ct);}return result;}
 public async Task<OperationResult<JournalItem>> ReverseAsync(Guid id,DateOnly date,string reason,Guid by,CancellationToken ct=default)=>await posting.ReverseAsync(id,date,reason,by,ct);
 public async Task<OperationResult<Guid>> TransferAsync(TransferRequest r,Guid by,CancellationToken ct=default){if(!await Active(ct))return OperationResult<Guid>.Failure("Finance must be explicitly activated before posting transfers.");var accounts=await db.FinancialAccounts.Where(x=>x.Id==r.SourceFinancialAccountId||x.Id==r.DestinationFinancialAccountId).ToArrayAsync(ct);if(accounts.Length!=2||accounts.Any(x=>!x.IsActive))return OperationResult<Guid>.Failure("Both financial accounts must be active.");var t=new FundTransfer(r.SourceFinancialAccountId,r.DestinationFinancialAccountId,r.Amount,r.Fee,r.FeeAccountId,r.TransferDate,r.Reference,r.Description,by);db.Add(t);var lines=new List<JournalLineRequest>{new(accounts.Single(x=>x.Id==r.DestinationFinancialAccountId).AccountId,r.Amount,0),new(accounts.Single(x=>x.Id==r.SourceFinancialAccountId).AccountId,0,r.Amount+r.Fee)};if(r.Fee>0){if(!r.FeeAccountId.HasValue)return OperationResult<Guid>.Failure("A fee expense account is required.");lines.Add(new(r.FeeAccountId.Value,r.Fee,0));}var j=await posting.PostAsync(new(r.TransferDate,"FundTransfer",t.Id,"Transfer",r.Description,lines),by,ct);if(!j.Succeeded)return OperationResult<Guid>.Failure(j.Errors);t.MarkPosted(j.Value!.Id);await db.SaveChangesAsync(ct);return OperationResult<Guid>.Success(t.Id);}
 public async Task<OperationResult<Guid>> ReconcileAsync(ReconciliationRequest r,Guid by,CancellationToken ct=default){var f=await db.FinancialAccounts.Include(x=>x.Account).SingleOrDefaultAsync(x=>x.Id==r.FinancialAccountId,ct);if(f is null)return OperationResult<Guid>.Failure("Financial account not found.");var book=await db.JournalLines.Where(x=>x.AccountId==f.AccountId&&x.JournalEntry.BusinessDate<=r.StatementDate).SumAsync(x=>x.Debit-x.Credit,ct);var x=new FinancialReconciliation(f.Id,r.StatementDate,r.ExternalOpeningBalance,r.ExternalClosingBalance,book,by);try{if(r.Complete)x.Complete(by);}catch(InvalidOperationException e){return OperationResult<Guid>.Failure(e.Message);}db.Add(x);await db.SaveChangesAsync(ct);return OperationResult<Guid>.Success(x.Id);}
 public async Task<IReadOnlyCollection<FiscalPeriod>> PeriodsAsync(CancellationToken ct=default)=>await db.FiscalPeriods.AsNoTracking().OrderByDescending(x=>x.StartDate).ToArrayAsync(ct);
 public Task<OperationResult<FiscalPeriod>> CreatePeriodAsync(string n,DateOnly s,DateOnly e,CancellationToken ct=default)=>administration.CreateFiscalPeriodAsync(new(n,s,e),ct);
 public async Task<OperationResult<FiscalPeriod>> ChangePeriodAsync(Guid id,FiscalPeriodStatus status,Guid by,CancellationToken ct=default){var x=await db.FiscalPeriods.SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return OperationResult<FiscalPeriod>.Failure("Fiscal period not found.");if(status==FiscalPeriodStatus.Closed&&await db.JournalEntries.AnyAsync(j=>j.FiscalPeriodId==id&&j.Lines.Count<2,ct))return OperationResult<FiscalPeriod>.Failure("Period contains unresolved journal integrity issues.");x.ChangeStatus(status,by,DateTimeOffset.UtcNow);await db.SaveChangesAsync(ct);return OperationResult<FiscalPeriod>.Success(x);}
 private async Task<bool> Active(CancellationToken ct){var a=await db.FinanceActivations.AsNoTracking().SingleAsync(ct);return a.AutomaticPostingEnabled&&a.CutoverDate.HasValue&&a.MandatoryMappingsApproved&&a.OpeningBalancesApproved&&a.ReconciliationReady;}
 private static FinanceAccountItem Item(Account x)=>new(x.Id,x.Code,x.Name,x.Type,x.NormalBalance,x.Kind,x.ParentId,x.IsActive,x.IsSystemControlled,x.HasPostings);
}
